custom_css:
/*
《 𝐒𝐀𝐓𝐈𝐒 - Big Avatar 》
作者: 睏暝@woolenbrave
版本：v3
此美化免費發布於旅程、尾巴鎮DC，請勿商用與二傳，二改請保留代碼作者標註。
*/

/*💠==字體==💠*/
@import url("https://fontsapi.zeoseven.com/79/main/result.css");
@import url('https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&display=swap');
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

body, select, code, .text_pole, #send_textarea, #chat .edit_textarea {
  font-family: var(--MainFont) !important;
}
/*💠==全局==💠*/
:root {
    /*文字*/
  --MainFont: "Lora", "Clear Han Serif", serif; /*正文字體*/
  --SecFont: "Noto Serif CJK";/*裝飾字體*/
  --TextSize: 1em; /*正文字體大小*/
  --LetterSpacing: 0.5px; /*字距*/
  --TextPadding: 10px; /*正文與聊天框邊界的距離*/
  --LineHeight: 1.7em; /*行高*/
  --LineSpace: 1.3em; /*段距*/
  --TextAlign: justify; /*對齊方式 justify 或 left*/
  --Indent: 2em; /*首行縮排*/

    /*主題元素顏色*/
  --ItemColor: var(--SmartThemeUnderlineColor);

    /*文案*/
  --CotColor: var(--ItemColor);
  --CotText: "무너질 이 별들까지 흐려질 영원에 묻힌\a차가운 네 입술 끝에 읽어줘 날";
  --Homeage: "다 부숴도 괜찮아\a지금 나의 상처를 봐줘\a지금 나를 치유해줘\a내 불안이 그저 가라앉도록\a네게 물들게";

    /*背景顏色*/
  --TopBarColor: var(--SmartThemeChatTintColor);/*頂底欄*/
  --PanelColor: var(--SmartThemeChatTintColor);/*左右欄*/
  --PanelColorPhone: var(--SmartThemeBlurTintColor);/*手機左右欄*/

  --SmartThemeRadius: 4px;/*全局圓角*/
  --Scrollbar: 5px; /*滾動條寬度*/
  --ChatBorder: 1px solid  color-mix(in srgb, var(--ItemColor) 30%, transparent);/*聊天氣泡外框*/
}

/*💠==頂欄&底欄圖標==💠🍓*/
:root {
    --TopBarIconColor: var(--ItemColor);/*顏色*/
    --TopBarIconOpacity: 0.3;/*透明度*/
    --TopBarIconSize: 21px;/*頂欄圖標大小*/
    --BottomBarIconSize: 19px;/*底欄圖標大小*/ 
    --Saturn: url('https://cdn.jsdelivr.net/gh/gigi5817-glitch/SATIS@main/saturn.svg');
}

/*💠==自定義樣式結束==💠*/


/*🪲聊天氣泡頂部佈局*/

.mes .avatar {
    height: 230px !important;/*頭像高度*/
}
.mes[is_user="false"] .avatar img {
    object-position: center 40% !important;/*char頭像裁切位置*/
}
.mes[is_user="true"] .avatar img {
    object-position: center 40% !important;/*user頭像裁切位置*/
}

.mes {
  padding-top: 280px !important;/*聊天氣泡上方留空*/
}
.mes .avatar {
  top: -175px;/*頭像高度位置*/
}
.mes .name_text {
  top: 205px;/*名字高度*/
}
.timestamp {
  top: 243px;/*日期高度*/
}

/* 🪲頭像容器 */
.mes .avatar {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    z-index: 0 !important;
    margin: 0 !important;
}

/* 頭像圖片 */
.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    position: absolute !important;
    object-fit: cover !important;
    -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 60%, rgba(0,0,0,0) 100%);
    mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 60%, rgba(0,0,0,0) 100%);
    border-radius: var(--SmartThemeRadius) !important;
    pointer-events: none;
}

/*🪲正文與聊天氣泡*/

/* 對白樣式 */
.mes_text q {
  margin: 0 6px 0 0px;
  border-bottom: 1px dotted color-mix(in srgb, var(--SmartThemeQuoteColor) 35%, transparent) !important;
}

/* 聊天氣泡邊距 */
#chat { padding: 8px 0px 8px var(--Scrollbar);}

/* 手機端聊天框 隱藏滾動條+對齊 */
@media screen and (max-width: 768px) {
    #chat::-webkit-scrollbar { display: none !important;}
    #chat { padding: 8px 5px !important; }}

#chat .mes {
  margin-top: 4px;
  flex-direction: column;
  align-items: center;
  border-radius: var(--SmartThemeRadius) !important;
  border: var(--ChatBorder) !important;
  position: relative !important;
  transform: none !important; 
  perspective: none !important;
  contain: layout; 
}

.mes_block {
  width: 100%;
  padding: 0 0 55px 0;
  position: static !important;
  transform: none !important; 
}

.mes_text {
  font-size: var(--TextSize);
  text-align: var(--TextAlign);
  width: 100% !important;
  line-height: var(--LineHeight);
  letter-spacing: var(--LetterSpacing);
  padding: 20px var(--TextPadding) 8px var(--TextPadding) !important;
  z-index: 20 !important;

}

.mes_text p {
    margin-bottom: var(--LineSpace) !important;
    text-indent: var(--Indent);
}

.mes_text p:last-child {
    margin-bottom: 0px !important;
}

/*引用塊*/
.mes_text blockquote {
  background: transparent;
  padding: 20px 20px;    
  border-radius: 10px;
  margin-bottom: 20px;
  border-left: 3px double color-mix(in srgb, var(--ItemColor) 60%, transparent);
  border-right: 3px double color-mix(in srgb, var(--ItemColor) 60%, transparent);
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--ItemColor) 20%, transparent);
  transition: border 0.6s ease, box-shadow 0.6s ease-out;
}

.mes_text blockquote:hover {
  border-left: 3px double color-mix(in srgb, var(--ItemColor) 100%, transparent);
  border-right: 3px double color-mix(in srgb, var(--ItemColor) 100%, transparent);
  box-shadow: inset 0 0 15px color-mix(in srgb, var(--ItemColor) 60%, transparent) !important;
}

/*代碼包裹 by @Junezz 復古MacOs*/
  code {
    background-color: transparent !important;
    color: var(--SmartThemeBodyColor) !important;
    font-family: var(--MainFont);
    border: 1px solid color-mix(in srgb, var(--ItemColor) 30%, transparent);
    box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 30%, transparent) !important;
    font-size: calc(var(--mainFontSize)* 0.98);
    padding: 0px 3px;
    line-height: var(--LineHeight) !important;
}
/*對齊*/
.last_mes .mesAvatarWrapper {
  padding-bottom: 0px;
}
.mes_block .ch_name {
  min-height: 0 !important;
  height: 0 !important;
}
/*選取文本樣式 by@potato_juice9*/
.mes_text ::selection {
    background: var(--SmartThemeQuoteColor) !important;
    color: var(--SmartThemeBlurTintColor);
}

/*🪲切換消息*/
.swipeRightBlock {
  position: absolute;
  justify-content: center;
  letter-spacing: 5px;
}
.swipe_left, .swipe_right {
  font-size: 18px;
}
.swipe_left::before,
.swipe_right::before {
  content: '✧';
  color: var(--ItemColor);
}

/*手機*/
@media (max-width: 768px) {
  .swipeRightBlock {
    left: 0;
    bottom: 20px;
  }
  .swipe_right {
    position: absolute;
    right: 12px;
    bottom: 0px;
  }
  .swipe_left {
    bottom: 15px;
  }
}

/*PC*/
@media (min-width: 769px) {
  .swipeRightBlock {
    left: 50px;
    bottom: 25px;
    flex-direction: row !important;
  }
  .swipe_right {
    position: static;
    order: 2;
    margin-left: 20px;
  }
  .swipes-counter {
    order: 1;
    width: 70px;
    text-align: center;
    font-variant-numeric: tabular-nums;
    color: var(--ItemColor);
  }
  .swipe_left {
    position: absolute;
    left: 50%;
    bottom: 22px;
    transform: translateX(-73px);
  }
}

/*🪲聊天氣泡頂部元素*/

.mes_buttons, .mes_edit_buttons, .mes_ghost, .mes .name_text, .mesIDDisplay, .mes_timer,
.tokenCounterDisplay,.icon-svg,.timestamp {
  color: var(--SmartThemeBodyColor);
  position: absolute !important;
  z-index: 20  !important;
}

/*🍺角色名字*/
.mes .name_text {
  left: 25px; 
  transform: none;
  font-size: 24px;
  letter-spacing: 4px;
  font-family: var(--SecFont);
  opacity: 1;
  color: var(--ItemColor) !important;
}

.mes .name_text::after {
  content: "。";
  margin-left: 1px;
  font-size: 24px;
  display: inline-block;
  opacity: 0.7;
}

/*🍺日期*/
.timestamp {
    font-size: 11.5px;
    letter-spacing: 1.5px;
    left: 27px;
    opacity: 1 !important;
    transition: opacity 0.6s ease, box-shadow 0.6s ease-out;
    font-family: var(--SecFont);
    color: var(--ItemColor)!important;
}

.mes_ghost:hover, .mes .name_text:hover, .timestamp:hover {
  opacity: 1 !important;
  text-shadow: 0 0 16px color-mix(in srgb, var(--ItemColor) 100%, transparent) !important;
}

.mes_reasoning_actions,
.mes_ghost,
#chat .mes_buttons .mes_button,
#chat .mes_edit_buttons .menu_button,
#chat .favorite-toggle-icon {
    color: var(--ItemColor) !important;
    opacity: 0.6 !important;
    transition: opacity 0.6s ease;
    filter:  none;
}

#chat .mes_buttons .mes_button:hover,
#chat .mes_edit_buttons .menu_button:hover,
#chat .mes_reasoning_actions .edit_button:hover,
#chat .favorite-toggle-icon:hover {
    opacity: 1 !important;
}

/*🍺小鉛筆*/
.mes_buttons {
  top: 15px !important;
  right: 10px;
  padding: 5px;
}

.mes_edit::before { 
  content: "\f56b";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900;
}

.extraMesButtonsHint::before {   
  content: "\f518";
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900; 
}

.extraMesButtonsHint {
  padding-right: 8px;
}

/*🍺正文edit按键*/
.mes_edit_buttons {
    top: 12px;
    padding: 0;
    filter: none;
    right: 14px;
}
#chat .mes_edit_buttons .menu_button {
    color: color-mix(in srgb, var(--ItemColor) 70%, transparent) !important;
    opacity: 1 !important;
    transition: opacity 0.6s ease;
    filter:  none;
}

/*🍺幽靈圖標*/
.mes_ghost {
    top: 55px; 
    right: 20px;
    transition: opacity 0.6s ease;
}

/*🍺訊息編號*/
.mesIDDisplay {
  top: 15px;
  font-size: 16px !important;
}

/*🍺Token*/
.tokenCounterDisplay { 
  top: 50px;
  font-size: 11px !important;
}

/*🍺計時*/
.mes_timer {
  top: 78px ;
  font-size: 11px !important;
}

.mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    left: 10px;
}

.mesIDDisplay::before {
  content: "Ch";
  margin-right: 5px;
  font-size: 13.5px !important;
}
.tokenCounterDisplay::before {
  content: "Tokens";
  margin-right: 5px;
  font-size: 8.5px !important;
}
.mes_timer::before {
  content: "Time";
  margin-right: 5px;
  font-size: 8.5px !important;
}

/*🍺三元素*/
.mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    padding: 2px 8px;
    opacity: 0.95 !important;
    transition: border 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.6s ease-out;
    font-family: var(--SecFont);
    color: var(--ItemColor) !important;
}
.mes_timer:hover, .tokenCounterDisplay:hover, .mesIDDisplay:hover {
  opacity: 1 !important;
  border: 1px solid color-mix(in srgb, var(--ItemColor) 100%, transparent);
  box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 100%, transparent) !important;
  transform: translateX(8px);
}
/*🍺毛玻璃小方塊*/
.mes_buttons,
#chat .mes_edit_buttons .menu_button,
.mes_timer, .mesIDDisplay, .tokenCounterDisplay {
    background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 60%, transparent) !important;
    border: 1px solid color-mix(in srgb, var(--ItemColor) 40%, transparent) !important;
    backdrop-filter: blur(6px) !important;
    -webkit-backdrop-filter: blur(6px) !important;
}

/*🪲頂欄 & 底欄 */
#top-settings-holder .drawer-icon::before,
#send_but::before,
#extensionsMenuButton::before,
#options_button::before {
    display: inline-block;
    background-repeat: no-repeat;
    background-position: center;
    font-family: "Font Awesome 6 Free", "Font Awesome 6 Brands" !important;
    font-weight: 900;
}

/* 頂欄圖標 */
#top-settings-holder > .drawer:nth-child(odd) .drawer-icon::before {
    content: "";
    mask-image: var(--Saturn) !important;
    -webkit-mask-image: var(--Saturn) !important;
    mask-size: var(--TopBarIconSize);
    -webkit-mask-size: var(--TopBarIconSize);
    mask-repeat: no-repeat;
    -webkit-mask-repeat: no-repeat;
    mask-position: center;
    -webkit-mask-position: center;
    background-color: var(--ItemColor);
    width: var(--TopBarIconSize);
    height: var(--TopBarIconSize);
    vertical-align: middle;
}
#top-settings-holder > .drawer:nth-child(even) .drawer-icon::before {
    content: "✧";
}

/*底欄圖標*/
#options_button::before       { content: "\f025"; }
#extensionsMenuButton::before { content: "✦";    }
#send_but::before             { content: "\f04b"; }

#options_button::before,
#extensionsMenuButton::before,
#send_but::before {
    background-size: var(--BottomBarIconSize);
    width: var(--BottomBarIconSize);
    height: var(--BottomBarIconSize);
}

/*懸浮動畫*/
:is(
    #quick-reply-rocket-button,
    #options_button,
    #extensionsMenuButton,
    #send_but,
    #top-settings-holder .drawer-icon
) {
    transition: opacity 0.2s ease-in-out, filter 0.2s ease-in-out !important;

    &:is(:hover, .openIcon) {
        opacity: 1 !important;
        filter: drop-shadow(0 0 6px var(--ItemColor)) !important;
    }
}

/* 頂欄 */
body.no-blur #top-bar,
#top-bar {
    background-color: var(--TopBarColor) !important;
    border-radius: 0;
}
body.no-blur #top-bar {
    padding-bottom: 0 !important;
}
#top-bar .drawer-icon,
.drawer-toggle .drawer-icon {
    font-size: var(--TopBarIconSize) !important;
    color: var(--TopBarIconColor) !important;
    opacity: var(--TopBarIconOpacity);
}

/* 底欄*/
body.no-blur #send_form,
#send_form {
    background-color: var(--TopBarColor) !important;
    border: none !important;
    outline: none !important;
    border-radius: 0 !important;
    border-top: var(--TopbarBorder) !important;
    padding: 1px 8px 2px 8px;
}
#sheld {
    position: absolute;
    bottom: 0;  
}
#rightSendForm>div, #leftSendForm>div {
    font-size: var(--BottomBarIconSize) !important;
    color: var(--TopBarIconColor) !important;
    opacity: var(--TopBarIconOpacity) !important;
}
#send_textarea::placeholder {
  opacity: 0;
}
/*消除底欄縫隙 by@_nak.a.ri*/
#form_sheld {
  margin: 0 auto !important;
}
/*修正版by咩野*/
body:not(.waifuMode) #sheld {
  top: var(--bottomFormBlockSize) !important;
  height: calc(100dvh - var(--bottomFormBlockSize)) !important;
  min-height: calc(100dvh - var(--bottomFormBlockSize)) !important;
}
/*🪲左右欄*/
#right-nav-panel, #left-nav-panel {
    background-color: var(--PanelColor) !important;
    border: none;
}
#left-nav-panel { box-shadow: 1px 0px 0 var(--PanelColor) !important; }
#right-nav-panel { box-shadow: -1px 0px 0 var(--PanelColor) !important; }

/* 手機端左右欄背景顏色 */
@media screen and (max-width: 768px) {
  #left-nav-panel, #right-nav-panel { background-color: var(--PanelColorPhone) !important; }
}
/* PC端左右欄佔滿全屏 */
@media screen and (min-width: 1025px) and (pointer: fine) {
  #left-nav-panel, #right-nav-panel { top: 0 !important; height: 100vh !important; max-height: 100vh !important; }
}
/*🪲右欄角色管理*/
.group_select:hover,
.avatar-container.interactable:hover,
.bogus_folder_select:hover, .character_select:hover {
    background-color: transparent; 
    box-shadow: inset 0 0 8px var(--ItemColor);
    border-radius: var(--SmartThemeRadius);
}
.group_select,
.bogus_folder_select, .character_select {
  padding: 10px;
  border: 1px solid transparent;
  border-radius: var(--SmartThemeRadius) !important;
}

#rm_button_characters, #rm_button_panel_pin_div, #lm_button_panel_pin_div, #WI_button_panel_pin_div {
    font-size: 1.15em !important;
    opacity:  1;
    padding-bottom: 5px;
}


/*群組頁面*/
#rm_group_members,
#rm_group_add_members {
  background: transparent;
  border: none;
}
/*角色收藏*/
.hotswap.avatars_inline { display: flex; flex-wrap: wrap; transition: all 1s ease; scrollbar-width: none; }
.hotswap.avatars_inline::-webkit-scrollbar { display: none; }
.hotswap.avatars_inline:hover { max-height: 300px; overflow: auto; }

/*收藏角色頭像框 by @rech0_viixi 雙色盒子*/
.character_select.is_fav .avatar {
  outline: 4px double var(--ItemColor);
}
.character_select.is_fav .ch_name {
  color: var(--ItemColor);
}

/*使用者角色選中頭像 by @mayonnaise58*/
.avatar-container.interactable.selected {
    background-color: transparent; 
    box-shadow: inset 0 0 8px var(--ItemColor);
    border-radius: var(--SmartThemeRadius) !important;
    border: none;
}
.avatar-container.interactable:hover {
    border-radius: calc(var(--SmartThemeRadius) + 2px);
    background-color: transparent !important;
    box-shadow: inset 0 0 8px var(--ItemColor);
}
/*角色管理按鈕*/
#charListFixedTop .rm_tag_filter .tag {
    background: transparent !important;
    color: var(--ItemColor);
    filter: none;
    border: 0;
    box-shadow: inset 0 0 8px color-mix(in srgb, var(--ItemColor) 50%, transparent) !important;
}


/* 🪲標題去陰影 */
#aistudio_proxy_button,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader
 {
    background-image: none;
    border-radius: var(--SmartThemeRadius) !important;
    padding: 4px 5px 4px 11px;
    margin-bottom: 5px;
    border: 1px solid color-mix(in srgb, var(--ItemColor) 20%, transparent);
    background-color: color-mix(in srgb, var(--ItemColor) 8%, transparent);
    transition: box-shadow 0.2s ease, border 0.2s ease;
}

/*🪲擴充頁面標題*/
#aistudio_proxy_button,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  border-radius: var(--SmartThemeRadius);
  padding: 6px 11px;
  margin-bottom: 6px !important;
  border: 1px solid color-mix(in srgb, var(--ItemColor) 20%, transparent);
  background-color: color-mix(in srgb, var(--ItemColor) 8%, transparent);
}
#aistudio_proxy_button:hover,
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
  border: 1px solid color-mix(in srgb, var(--ItemColor) 45%, transparent) !important;
  box-shadow: inset 0 0 5px color-mix(in srgb, var(--ItemColor) 45%, transparent) !important;
  filter: none !important;
}
/*擴充功能關閉條目*/
.extensions_info .extension_disabled {
  color: var(--SmartThemeBodyColor) !important;
}

/*🪲思維鏈*/
.mes_reasoning_details {

    margin-left: var(--TextPadding);
    margin-right: var(--TextPadding);
    position: relative !important;
}
/*思維鏈內容主體*/
.mes_reasoning {
    max-height: 480px; /*思維鏈內容開啟高度*/
    overflow-y: auto;
    overflow-x: hidden;
    color: var(--SmartThemeBodyColor) !important;
    margin-bottom: 18px;
    box-shadow: inset 0 0 10px color-mix(in srgb, var(--ItemColor) 20%, transparent);
    border: 1px dotted color-mix(in srgb, var(--ItemColor) 20%, transparent);
    background: linear-gradient(
        to bottom,
        color-mix(in srgb, var(--ItemColor) 15%, transparent) 0%,
        color-mix(in srgb, var(--ItemColor) 0%, transparent) 100%) !important;
    margin-top: 35px;
}
.mes_reasoning_header:hover {
  filter: drop-shadow(0 0 5px var(--ItemColor));
  transition: filter 0.6s ease;
}
/*隱藏原始箭頭*/
.mes_reasoning_details .mes_reasoning_arrow {
    display: none !important;
}
.mes_reasoning_header_block {
    margin: 0;
}
/*思維鏈編輯框*/
.reasoning_edit_textarea { 
  margin-top: 50px; margin-bottom: 15px; 
}
/*思維鏈小鉛筆*/
.mes_reasoning_actions.flex-container {
    position: absolute !important;
    top: 65px !important;
    right: 0; 
    z-index: 30;
}
/*思維鏈edit按鈕*/
.mes_reasoning_edit_done,
.mes_reasoning_edit_cancel,
.mes_reasoning_delete {
    margin-top: 4px !important;
    filter: none !important;
}

/*🥝思維鏈標題區塊*/
.mes_reasoning_header {
    font-size: 0 !important;
    display: flex !important; 
    justify-content: flex-end !important;
